UPDATE t_risk_policy
SET status = #{status}, status_type = #{statusType}, updated_at = CURRENT_TIMESTAMP
WHERE policy_code = #{policyCode}

UPDATE t_risk_limit_rule
SET status = #{status}, status_type = #{statusType}, updated_at = CURRENT_TIMESTAMP
WHERE rule_code = #{ruleCode}

UPDATE t_risk_blocklist
SET status = #{status}, status_type = #{statusType}, updated_at = CURRENT_TIMESTAMP
WHERE block_code = #{blockCode}

UPDATE t_risk_monitor_rule
SET status = #{status}, status_type = #{statusType}, updated_at = CURRENT_TIMESTAMP
WHERE monitor_code = #{monitorCode}

UPDATE t_risk_review_order
SET status = #{status}, status_type = #{statusType}, reviewer = #{reviewer}, updated_at = CURRENT_TIMESTAMP
WHERE review_no = #{reviewNo}
